<script lang="ts">
 import {onDestroy,untrack} from 'svelte';
 import {Session} from '$lib/stores';
 import {createStaffClient,can,effectText,downloadHistoryCsv,WorkspaceError,type StaffClient,type Authority} from './staff-client';
 let client=$state.raw<StaffClient>();
 let epoch=0,closed=false;
 let authority=$state<Authority>(),rows=$state<any[]>([]),reviewers=$state<any[]>([]),total=$state(0),page=$state(1),view=$state('queue'),status=$state('waiting'),assigned=$state('all'),priority=$state(''),search=$state('');
 let from=$state(''),to=$state(''),operation=$state(''),exporting=$state(false),exportReview=$state<{query:string;label:string}>();let exportEpoch=0;
 const operations=[['create','Report submitted'],['accept','Accepted'],['reject','Refused'],['delete','Report deleted'],['claim','Claimed'],['unclaim','Unclaimed'],['assign','Assigned'],['progress','Work started'],['priority','Priority changed'],['appeal','Appeal submitted'],['reopen','Reopened'],['correct','Local correction']];
 let pending=$state(false),error=$state(''),notice=$state(''),review=$state<any>(),action=$state(''),reason=$state(''),pendingPath=$state('');
 const allowed=$derived(can(authority,view==='history'?'report.history':'report.update'));
 function guard(){const generation=epoch,session=$Session;return()=>{if(closed||generation!==epoch||session!==$Session)throw Error('Your signed-in account changed. Open the workspace again.');};}
 function clear(){epoch++;client?.dispose();client=undefined;authority=undefined;rows=[];reviewers=[];review=undefined;reason='';pending=false;error='';notice='';pendingPath='';total=0;page=1;view='queue';status='waiting';assigned='all';priority='';search='';from='';to='';operation='';exportReview=undefined;exporting=false;exportEpoch++;}
 $effect(()=>{const session=$Session;untrack(()=>{clear();if(session?.identity?.id)void load();});});
 onDestroy(()=>{closed=true;clear();});
 function failure(cause:unknown){error=cause instanceof Error?cause.message:'The action could not be confirmed.';if(cause instanceof WorkspaceError&&[401,403].includes(cause.status)){rows=[];review=undefined;authority=undefined;client?.dispose();client=undefined;}}
 async function load(){if(pending||!$Session?.identity?.id)return;const assert=guard();pending=true;error='';try{const selected=client??await createStaffClient($Session.identity.id,assert);assert();client=selected;authority=selected.authority;if(!can(authority,view==='history'?'report.history':'report.update'))throw new WorkspaceError('Your current account does not have access to this view.',403);
  const result=await selected.read('/staff/'+(view==='queue'?'reports':'history')+'?'+queryString());assert();if(!Array.isArray(result.data)||!Number.isSafeInteger(result.total))throw Error('The queue could not be checked.');rows=result.data;total=result.total;
  if(can(authority,'report.assign')&&view==='queue'){const directory=await selected.read('/staff/reviewers');assert();reviewers=Array.isArray(directory.data)?directory.data:[];}
 }catch(cause){try{assert();failure(cause);}catch{}}finally{try{assert();pending=false;}catch{}}}
 function queryString(csv=false){const query=new URLSearchParams({page:String(csv?1:page),search});if(view==='queue'){query.set('status',status);query.set('assigned',assigned);if(priority)query.set('priority',priority);}else{if(from)query.set('from',from);if(to)query.set('to',to);if(operation)query.set('operation',operation);if(csv)query.set('export','csv');}return query.toString().replace(/^\?/, '');}
 function reviewExport(){if(pending||exporting||view!=='history'||!can(authority,'report.history'))return;exportReview={query:queryString(true),label:`${from||'All earlier dates'} through ${to||'the latest date'} (UTC); ${operations.find(row=>row[0]===operation)?.[1]||'all operations'}; ${search?'search: '+search:'no search restriction'}`};error='';}
 function cancelExport(){exportEpoch++;exportReview=undefined;exporting=false;}
 async function exportHistory(){if(pending||exporting||!client||!exportReview)return;const current=guard(),selected=client,reviewed=exportReview,n=++exportEpoch;const assert=()=>{current();selected.check();if(n!==exportEpoch||view!=='history'||exportReview!==reviewed||queryString(true)!==reviewed.query)throw Error('The history view changed. Review the export again.');};exporting=true;error='';notice='';try{assert();const result=await selected.read('/staff/history?'+reviewed.query);assert();const saved=downloadHistoryCsv(result,assert);assert();notice=`Prepared a local CSV download with ${saved.exported} of ${saved.total} matching history entries.${saved.truncated?' This export is limited; narrow the filters for the remaining entries.':''}`;exportReview=undefined;}catch(cause){try{current();selected.check();if(n===exportEpoch){failure(cause);exportReview=undefined;}}catch{}}finally{if(n===exportEpoch)exporting=false;}}
 async function switchView(next:string){if(pending||exporting)return;exportReview=undefined;view=next;page=1;rows=[];review=undefined;await load();}
 async function open(row:any,selectedAction:string){if(pending||!client)return;const assert=guard();pending=true;error='';notice='';review=undefined;reason='';action=selectedAction;
  try{if(selectedAction==='reopen'){review={report:{id:row.id??row.reportId,version:row.version},reopen:true};}
  else{const id=row.id??row.reportId,route=selectedAction==='correct'?'/correction':'/review'+(selectedAction==='delete'?'?intent=delete':'');const value=await client.read('/staff/reports/'+encodeURIComponent(id)+route);assert();review={...value.context,targetHref:value.targetHref};}
  }catch(cause){try{assert();failure(cause);}catch{}}finally{try{assert();pending=false;}catch{}}
 }
 function cancel(){if(!pending){review=undefined;reason='';action='';}}
 async function confirm(){if(pending||!client||!review||!reason.trim())return;const assert=guard(),selected=client,context=review,id=context.report?.id??context.reportId;
  const suffix=action==='correct'?'correction':action==='reopen'?'reopen':'decision',path='/staff/reports/'+encodeURIComponent(id)+'/'+suffix;
  const command=action==='correct'?{contextHash:context.contextHash,reason}:action==='reopen'?{version:context.report.version,reason}:{action,expectedReportVersion:context.report.version,expectedContextHash:context.contextHash,expectedEffect:action==='delete'?context.effect:action==='accept'?context.acceptEffect:{},notes:reason};
  pending=true;error='';notice='';pendingPath=path;try{const result=await selected.mutate(path,command);assert();notice='Saved. The action has a durable receipt and history entry.';review=undefined;reason='';pendingPath='';}catch(cause){try{assert();failure(cause);}catch{}}finally{try{assert();pending=false;}catch{}}if(!pendingPath)await load();
 }
 async function work(row:any,operation:string,value?:string){if(pending||!client)return;const assert=guard(),selected=client,path='/staff/reports/'+encodeURIComponent(row.id)+'/work';pending=true;error='';notice='';pendingPath=path;
  try{await selected.mutate(path,{version:row.version,action:operation,...(value?{value}:{})});assert();notice='Queue updated.';pendingPath='';}catch(cause){try{assert();failure(cause);}catch{}}finally{try{assert();pending=false;}catch{}}if(!pendingPath)await load();
 }
 async function reconcile(){if(pending||!client||!pendingPath)return;const assert=guard();pending=true;error='';try{await client.reconcile(pendingPath);assert();notice='The earlier action was confirmed. The queue now shows its saved result.';pendingPath='';review=undefined;}catch(cause){try{assert();failure(cause);if(cause instanceof WorkspaceError&&cause.status===404)error='No receipt is available yet. Do not repeat the action. Check history or ask an administrator to reconcile it.';}catch{}}finally{try{assert();pending=false;}catch{}}if(!pendingPath)await load();}
 function summary(effect:any){if(effect?.action==='instance_soft_hide')return 'Hidden on this instance only';if(effect?.action==='grant_group_leadership')return 'Local group leadership granted';if(effect?.action==='restore_local_visibility')return 'Local visibility restored';if(effect?.action==='restore_previous_group_membership')return 'Previous local membership restored';if(effect?.action==='reopen')return 'Reopened; previous content effects are unchanged';return 'Report workflow only';}
</script>
<svelte:head><title>Moderator queue</title></svelte:head>
<section class="space-y-5">
 <header class="space-y-2"><h1 class="text-2xl font-semibold">Moderator queue</h1><p>Reports for this instance. These tools use your normal signed-in account. They do not grant original-service or publishing authority.</p><nav class="flex flex-wrap gap-4"><a class="underline" href="/staff">Staff home</a><a class="underline" href="/my/reports">My reports — only my submissions</a></nav></header>
 {#if !$Session?.identity?.id}<p>Sign in with an authorized moderator account to continue.</p><a class="underline" href="/auth/login">Sign in</a>{/if}
 <nav aria-label="Moderation views" class="flex gap-3"><button class="rounded border px-3 py-2" aria-current={view==='queue'?'page':undefined} disabled={pending||exporting} onclick={()=>switchView('queue')}>Queue</button>{#if can(authority,'report.history')}<button class="rounded border px-3 py-2" aria-current={view==='history'?'page':undefined} disabled={pending||exporting} onclick={()=>switchView('history')}>Decision history</button>{/if}</nav>
 {#if error}<p role="alert" class="text-destructive">{error}</p>{/if}{#if notice}<p role="status">{notice}</p>{/if}
 {#if pendingPath&&client?.pending(pendingPath)}<section class="rounded border p-4"><p>An earlier action has an unconfirmed result. It will not be repeated automatically.</p><button class="rounded border p-2" disabled={pending} onclick={reconcile}>Check action receipt</button></section>{/if}
 <form class="flex flex-wrap gap-3 items-end" onsubmit={event=>{event.preventDefault();if(exporting)return;exportReview=undefined;page=1;void load();}}>
  <label>Search {view==='history'?'by target, reviewer or reason':'by subject, reason or reporter'}<input class="block rounded border p-2" maxlength="200" disabled={exporting} bind:value={search}/></label>
  {#if view==='queue'}<label>Status<select class="block rounded border p-2" bind:value={status}><option value="waiting">Waiting</option><option value="accepted">Accepted</option><option value="refused">Refused</option><option value="autoresolved">Resolved automatically</option><option value="all">All</option></select></label><label>Assignment<select class="block rounded border p-2" bind:value={assigned}><option value="all">Everyone</option><option value="mine">Assigned to me</option><option value="unassigned">Unassigned</option></select></label><label>Priority<select class="block rounded border p-2" bind:value={priority}><option value="">All priorities</option>{#each ['low','normal','high','urgent'] as value}<option value={value}>{value}</option>{/each}</select></label>{/if}
  {#if view==='history'}<label>From date (UTC)<input class="block rounded border p-2" type="date" min="1970-01-01" max="9999-12-31" bind:value={from} disabled={exporting}/></label><label>Through date (UTC)<input class="block rounded border p-2" type="date" min="1970-01-01" max="9999-12-31" bind:value={to} disabled={exporting}/></label><label>Operation<select class="block rounded border p-2" bind:value={operation} disabled={exporting}><option value="">All operations</option>{#each operations as entry}<option value={entry[0]}>{entry[1]}</option>{/each}</select></label>{/if}
  <button class="rounded border p-2" disabled={pending||exporting||!$Session?.identity?.id}>Refresh</button>
 </form>
 {#if view==='history'&&can(authority,'report.history')}<button class="rounded border p-2" disabled={pending||exporting} onclick={reviewExport}>Export filtered history</button>{/if}
 {#if exportReview}<section class="rounded border p-4 space-y-3" aria-label="Review history export"><h2 class="text-xl font-semibold">Download a private history copy</h2><p>{exportReview.label}</p><p>This exports the newest matching entries, not only the current page: at most 250 rows and 256 KiB. Larger results are explicitly marked as limited; narrow the filters to get a smaller set. The file includes reviewer names and decision reasons, but not raw private effect records.</p><p>The UTF-8 CSV is saved only to this browser’s downloads. Nothing is emailed, uploaded or shared automatically. Keep this staff-only file private.</p><div class="flex gap-3"><button class="rounded border p-2" onclick={cancelExport}>Cancel export</button><button class="rounded border p-2" disabled={pending||exporting} onclick={exportHistory}>Download CSV</button></div>{#if exporting}<p role="status">Preparing the filtered export…</p>{/if}</section>{/if}
 {#if pending}<p role="status">Checking moderation work…</p>{/if}
 {#if allowed&&!pending&&!rows.length}<p>No reports match this view.</p>{/if}
 {#if view==='queue'}
  {#each rows as row (row.id)}<article class="rounded border p-4 space-y-3"><div class="flex flex-wrap justify-between gap-2"><h2 class="font-semibold">{row.reason}</h2><span>{row.status} · {row.priority} priority</span></div><p>{#if row.targetHref}<a class="underline" href={row.targetHref}>{row.targetName||row.category.replaceAll('_',' ')}</a>{:else}{row.targetName||row.category.replaceAll('_',' ')}{/if} · reported by {row.submitter}</p><p>{row.assignee?'Assigned to '+row.assignee:'Unassigned'}{row.workState==='in_progress'?' · In progress':''}{row.appealState==='pending'?' · Appeal waiting':''}</p><details><summary>Report reference</summary><p>{row.id} · subject {row.objectId}</p></details><div class="flex flex-wrap gap-2"><button class="rounded border p-2" disabled={pending} onclick={()=>open(row,'accept')}>Review report</button>
   {#if row.status==='waiting'}{#if !row.assignedTo}<button class="rounded border p-2" disabled={pending} onclick={()=>work(row,'claim')}>Claim</button>{:else if row.assignedTo===authority?.actorId}<button class="rounded border p-2" disabled={pending} onclick={()=>work(row,'unclaim')}>Unclaim</button>{#if row.workState!=='in_progress'}<button class="rounded border p-2" disabled={pending} onclick={()=>work(row,'progress')}>Start work</button>{/if}{/if}<label>Priority<select class="rounded border p-2" value={row.priority} disabled={pending} onchange={event=>work(row,'priority',event.currentTarget.value)}>{#each ['low','normal','high','urgent'] as value}<option value={value}>{value}</option>{/each}</select></label>{/if}
   {#if row.status==='waiting'&&can(authority,'report.assign')}<label>Assign to<select class="rounded border p-2" value={row.assignedTo??''} disabled={pending} onchange={event=>event.currentTarget.value?work(row,'assign',event.currentTarget.value):work(row,'unclaim')}><option value="">Unassigned</option>{#each reviewers as reviewer}<option value={reviewer.id}>{reviewer.name}</option>{/each}</select></label>{/if}
   {#if can(authority,'report.delete')}<button class="rounded border p-2" disabled={pending} onclick={()=>open(row,'delete')}>Review report deletion</button>{/if}
   {#if row.status!=='waiting'&&can(authority,'report.correct',true)}<button class="rounded border p-2" disabled={pending} onclick={()=>open(row,'reopen')}>Reopen review</button>{#if row.status==='accepted'}<button class="rounded border p-2" disabled={pending} onclick={()=>open(row,'correct')}>Review local correction</button>{/if}{/if}
  </div></article>{/each}
 {:else}
  {#each rows as row (row.id)}<article class="rounded border p-4 space-y-2"><h2 class="font-semibold">{row.operation} · {row.actor}</h2><p>{row.category.replaceAll('_',' ')} {row.objectId} · {new Date(row.createdAt).toLocaleString()}</p>{#if row.reason}<p class="whitespace-pre-wrap">{row.reason}</p>{/if}<p>{summary(row.effect)}</p><details><summary>Decision reference</summary><p>Report {row.reportId} · revision {row.version}</p></details></article>{/each}
 {/if}
 {#if total>25}<nav aria-label="Queue pages" class="flex gap-3"><button class="rounded border p-2" disabled={pending||exporting||page===1} onclick={()=>{page--;void load();}}>Previous</button><span>Page {page}</span><button class="rounded border p-2" disabled={pending||exporting||page*25>=total} onclick={()=>{page++;void load();}}>Next</button></nav>{/if}
 {#if review}<section class="rounded border-2 p-5 space-y-4" aria-label="Review moderation consequence">
  <h2 class="text-xl font-semibold">{action==='correct'?'Correct a local decision':action==='reopen'?'Reopen this report':action==='delete'?'Delete this report only':'Review report decision'}</h2>
  {#if review.targetHref}<a class="underline" href={review.targetHref}>Open the exact reported subject</a>{/if}
  {#if review.report?.details}<p class="whitespace-pre-wrap">{review.report.details}</p>{/if}
  {#if action==='correct'}<p>Restore the recorded previous local state of <strong>{review.targetName}</strong>. The original decision stays in history. This does not restore withdrawn original content or copies elsewhere.</p>{#if review.effect?.action==='restore_previous_group_membership'}<p>Remove the local leadership granted to <strong>{review.previousEffect?.new_member_name||'the recorded claimant'}</strong>.</p>{#if review.effect.previousMembership===null}<p>Remove only the membership added by that decision. There was no earlier membership to restore.</p>{:else}<p>Restore the previous membership name <strong>{review.effect.previousMembership.name}</strong>, with {review.effect.previousMembership.is_officer?'officer permissions':'ordinary member permissions'} and no leadership permissions.</p>{/if}{:else}<p>Remove only this instance’s local hide. The original source must still be available; this action cannot restore withdrawn source content.</p>{/if}
  {:else if action==='reopen'}<p>Reopen this report for review. This changes its workflow only: earlier hiding or group leadership is not automatically reversed. Use the separate local correction review for a supported inverse.</p>
  {:else}<p class="font-medium">{effectText(review,action)}</p>{/if}
  {#if !['correct','reopen','delete'].includes(action)&&review.report.status==='waiting'}<p>Subject: {review.target?.label||'Currently unavailable'} · {review.reason?.label}</p><label>Decision<select class="block rounded border p-2" bind:value={action} disabled={pending}><option value="accept">Accept report</option><option value="refuse">Refuse report</option></select></label>{#if action==='accept'&&!review.acceptAllowed}<p>This acceptance is not available with the current target state and your current grants. Refresh or ask the appropriate administrator.</p>{/if}{/if}
  {#if ['accept','refuse'].includes(action)&&review.report.status!=='waiting'}<p>This report has already been decided. Use Reopen review or Review local correction from the queue for a new authorized action.</p>{/if}
  <label class="block">Reason shown in this report’s decision history<textarea class="block w-full rounded border p-2" rows="4" maxlength="4000" bind:value={reason} disabled={pending}></textarea></label>
  <div class="flex gap-3"><button class="rounded border p-2" disabled={pending} onclick={cancel}>Cancel</button><button class="rounded border p-2" disabled={pending||!reason.trim()||(action==='accept'&&!review.acceptAllowed)||(['accept','refuse'].includes(action)&&review.report.status!=='waiting')} onclick={confirm}>Confirm {action==='correct'?'local correction':action==='reopen'?'reopen':action==='delete'?'report deletion':action==='accept'?'acceptance':'refusal'}</button></div>
 </section>{/if}
</section>
